static
CHAR16 * GetAltMonth (VOID) {
    CHAR16 *AltMonth;

    switch (NowMonth) {
        case  1: AltMonth = L"b";  break;
        case  2: AltMonth = L"c";  break;
        case  3: AltMonth = L"f";  break;
        case  4: AltMonth = L"h";  break;
        case  5: AltMonth = L"j";  break;
        case  6: AltMonth = L"k";  break;
        case  7: AltMonth = L"n";  break;
