    struct razer_report response = {0};

    switch(device->usb_pid) {
    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V4:
    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V4_X:
    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V4_PRO:
