    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V3_PRO_WIRELESS:
    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V3_MINI_WIRELESS:
    case USB_DEVICE_ID_RAZER_DEATHSTALKER_V2_PRO_WIRELESS:
