            request.transaction_id.id = 0x3F;
            razer_send_payload(device, &request, &response);
            break;

        default:
            printk(KERN_WARNING "razerkbd: Breathing only accepts '1' (1byte). RGB (3byte). RGB, RGB (6byte)\n");
            return -EINVAL;
        }
        break;

    case USB_DEVICE_ID_RAZER_TARTARUS_V2:
