    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V4_X:
    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V4_PRO:
    case USB_DEVICE_ID_RAZER_BLACKWIDOW_V4_75PCT:
