    case USB_DEVICE_ID_RAZER_VIPER_V3_PRO_WIRELESS:
        request.transaction_id.id = 0x1f;
        break;

    default:
        request.transaction_id.id = 0xFF;
        break;
    }

    razer_send_payload(device, &request, &response);

