	cursor=cursor->next;
      }
      printFullDescription(doc,in,children,type,ns,ns_ows,nc1,vid,fromDb,serviceType);
      freeElements(&children);
      free(children);
    }else{
      if(nc2!=NULL){
	xmlAddChild(nc1,nc2);
      }
    }
    e=e->next;
  }
}

/**
 * Generate a wps:Execute XML document.
 * 
 * @param m the conf maps containing the main.cfg settings
 * @param request the map representing the HTTP request
 * @param pid the process identifier linked to a service
 * @param serv the serv structure created from the zcfg file
 * @param service the service name
 * @param status the status returned by the service
 * @param inputs the inputs provided
 * @param outputs the outputs generated by the service
 */
void printProcessResponse(maps* pmsConf,map* request, int pid,service* serv,const char* service,int status,maps* inputs,maps* outputs){
  xmlNsPtr ns,ns_ows,ns_xlink;
  xmlNodePtr nr,n,nc,nc1=NULL,nc3;
  xmlDocPtr doc;
  time_t time1;  
  time(&time1);
  nr=NULL;

  doc = xmlNewDoc(BAD_CAST "1.0");
  map* version=getMapFromMaps(pmsConf,"main","rversion");
  int vid=getVersionId(version->value);
  n = printWPSHeader(doc,pmsConf,"Execute",root_nodes[vid][2],(version!=NULL?version->value:"1.0.0"),2);
  int wpsId=zooXmlAddNs(NULL,schemas[vid][2],"wps");
  ns=usedNs[wpsId];
  int owsId=zooXmlAddNs(NULL,schemas[vid][1],"ows");
  ns_ows=usedNs[owsId];
  int xlinkId=zooXmlAddNs(NULL,"http://www.w3.org/1999/xlink","xlink");
  ns_xlink=usedNs[xlinkId];
  bool hasStoredExecuteResponse=false;
  char stored_path[1024];
  memset(stored_path,0,1024);

  if(vid==0){
    char tmp[256];
    char url[1024];
    memset(tmp,0,256);
    memset(url,0,1024);
    maps* tmp_maps=getMaps(pmsConf,"main");
    if(tmp_maps!=NULL && tmp_maps->content!=NULL){
      map* tmpm1=getMap(tmp_maps->content,"serverAddress");
      /**
       * Check if the ZOO Service GetStatus is available in the local directory.
       * If yes, then it uses a reference to an URL which the client can access
       * to get information on the status of a running Service (using the 
       * percentCompleted attribute). 
       * Else fallback to the initial method using the xml file to write in ...
       */
      map* cwdMap=getMapFromMaps(pmsConf,"main","servicePath");
      struct stat myFileInfo;
      int statRes;
      char* pcaFilePath;
      if(cwdMap!=NULL){
        pcaFilePath=(char*)malloc((strlen(cwdMap->value)+17)*sizeof(char));
        sprintf(pcaFilePath,"%s/GetStatus.zcfg",cwdMap->value);
      }else{
        char ntmp[1024];
        if(zGetCwd(ntmp,1024)==NULL){
          ZOO_DEBUG(_("Unable to get the current working directory."));
          return ;
        }
        pcaFilePath=(char*)malloc((strlen(ntmp)+17)*sizeof(char));
        sprintf(pcaFilePath,"%s/GetStatus.zcfg",ntmp);
      }
      statRes=stat(pcaFilePath,&myFileInfo);
      if(statRes==0){
        char currentSid[128];
        map* tmpm=getMap(tmp_maps->content,"rewriteUrl");
        map *tmp_lenv=NULL;
        tmp_lenv=getMapFromMaps(pmsConf,"lenv","usid");
        if(tmp_lenv==NULL)
          sprintf(currentSid,"%i",pid);
        else
          sprintf(currentSid,"%s",tmp_lenv->value);
        if(tmpm==NULL || strcasecmp(tmpm->value,"false")==0){
          sprintf(url,"%s?request=Execute&service=WPS&version=1.0.0&Identifier=GetStatus&DataInputs=sid=%s&RawDataOutput=Result",tmpm1->value,currentSid);
        }else{
          if(strlen(tmpm->value)>0)
            if(strcasecmp(tmpm->value,"true")!=0)
              sprintf(url,"%s/%s/GetStatus/%s",tmpm1->value,tmpm->value,currentSid);
            else
              sprintf(url,"%s/GetStatus/%s",tmpm1->value,currentSid);
          else
            sprintf(url,"%s/?request=Execute&service=WPS&version=1.0.0&Identifier=GetStatus&DataInputs=sid=%s&RawDataOutput=Result",tmpm1->value,currentSid);
        }
      }else{
        int lpid;
        map* tmpm2=getMapFromMaps(pmsConf,"lenv","usid");
        map* tmpm3=getMap(tmp_maps->content,"tmpUrl");
        if(tmpm1!=NULL && tmpm3!=NULL){
          if( strncasecmp( tmpm3->value, "http://", 7) == 0 ||
              strncasecmp( tmpm3->value, "https://", 8 ) == 0 ){
            sprintf(url,"%s/%s_%s.xml",tmpm3->value,service,tmpm2->value);
          }else
            sprintf(url,"%s/%s_%s.xml",tmpm1->value,service,tmpm2->value);
        }
      }
      if(tmpm1!=NULL){
      	sprintf(tmp,"%s",tmpm1->value);
      }
      int lpid;
      map* tmpm2=getMapFromMaps(pmsConf,"lenv","usid");
      tmpm1=getMapFromMaps(pmsConf,"main","TmpPath");
      sprintf(stored_path,"%s/%s_%s.xml",tmpm1->value,service,tmpm2->value);
    }

    xmlNewProp(n,BAD_CAST "serviceInstance",BAD_CAST tmp);
    map* test=getMap(request,"storeExecuteResponse");
    if(test!=NULL && strcasecmp(test->value,"true")==0){
      xmlNewProp(n,BAD_CAST "statusLocation",BAD_CAST url);
      hasStoredExecuteResponse=true;
    }

    nc = xmlNewNode(ns, BAD_CAST "Process");
    map* tmp2=getMap(serv->content,"processVersion");
    if(tmp2!=NULL)
      xmlNewNsProp(nc,ns,BAD_CAST "processVersion",BAD_CAST tmp2->value);
    else
      xmlNewNsProp(nc,ns,BAD_CAST "processVersion",BAD_CAST "1");

    map* tmpI=getMapFromMaps(pmsConf,"lenv","oIdentifier");
    printDescription(nc,ns_ows,tmpI->value,serv->content,0);

    xmlAddChild(n,nc);

    nc = xmlNewNode(ns, BAD_CAST "Status");
    const struct tm *tm;
    size_t len;
    time_t now;
    char *tmp1;
    map *tmpStatus;

    now = time ( NULL );
    tm = localtime ( &now );

    tmp1 = (char*)malloc((TIME_SIZE+1)*sizeof(char));

    len = strftime ( tmp1, TIME_SIZE, zDateFormat, tm );

    xmlNewProp(nc,BAD_CAST "creationTime",BAD_CAST tmp1);

    char sMsg[2048];
    switch(status){
    case SERVICE_SUCCEEDED:
      nc1 = xmlNewNode(ns, BAD_CAST "ProcessSucceeded");
      sprintf(sMsg,_("The service \"%s\" ran successfully."),serv->name);
      nc3=xmlNewText(BAD_CAST sMsg);
      xmlAddChild(nc1,nc3);
      break;
    case SERVICE_STARTED:
      nc1 = xmlNewNode(ns, BAD_CAST "ProcessStarted");
      tmpStatus=getMapFromMaps(pmsConf,"lenv","status");
      xmlNewProp(nc1,BAD_CAST "percentCompleted",BAD_CAST tmpStatus->value);
      sprintf(sMsg,_("The ZOO service \"%s\" is currently running. Please reload this document to get the up-to-date status of the service."),serv->name);
      nc3=xmlNewText(BAD_CAST sMsg);
      xmlAddChild(nc1,nc3);
      break;
    case SERVICE_ACCEPTED:
      nc1 = xmlNewNode(ns, BAD_CAST "ProcessAccepted");
      sprintf(sMsg,_("The service \"%s\" was accepted by the ZOO-Kernel and is running as a background task. Please access the URL in the statusLocation attribute provided in this document to get the up-to-date status and results."),serv->name);
      nc3=xmlNewText(BAD_CAST sMsg);
      xmlAddChild(nc1,nc3);
      break;
    case SERVICE_FAILED:
      nc1 = xmlNewNode(ns, BAD_CAST "ProcessFailed");
      map *errorMap;
      map *te;
      te=getMapFromMaps(pmsConf,"lenv","code");
      if(te!=NULL)
	errorMap=createMap("code",te->value);
      else
	errorMap=createMap("code","NoApplicableCode");
      te=getMapFromMaps(pmsConf,"lenv","message");
      if(te!=NULL)
	addToMap(errorMap,"text",_ss(te->value));
      else
	addToMap(errorMap,"text",_("No more information available"));
      nc3=createExceptionReportNode(pmsConf,errorMap,0);
      freeMap(&errorMap);
      free(errorMap);
      xmlAddChild(nc1,nc3);
      break;
    default :
      printf(_("error code not know : %i\n"),status);
      //exit(1);
      break;
    }
    xmlAddChild(nc,nc1);
    xmlAddChild(n,nc);
    free(tmp1);

#ifdef DEBUG
    fprintf(stderr,"printProcessResponse %d\n",__LINE__);
#endif

    map* lineage=getMap(request,"lineage");
    if(lineage!=NULL && strcasecmp(lineage->value,"true")==0){
      nc = xmlNewNode(ns, BAD_CAST "DataInputs");
      maps* mcursor=inputs;
      elements* scursor=NULL;
      while(mcursor!=NULL /*&& scursor!=NULL*/){
	scursor=getElements(serv->inputs,mcursor->name);
	printIOType(doc,nc,ns,ns_ows,ns_xlink,scursor,mcursor,"Input",vid);
	mcursor=mcursor->next;
      }
      xmlAddChild(n,nc);

      nc = xmlNewNode(ns, BAD_CAST "OutputDefinitions");
      mcursor=outputs;
      scursor=NULL;
      while(mcursor!=NULL){
	scursor=getElements(serv->outputs,mcursor->name);
	printOutputDefinitions(doc,nc,ns,ns_ows,scursor,mcursor,"Output");
	mcursor=mcursor->next;
      }
      xmlAddChild(n,nc);
    }
  }

  /**
   * Display the process output only when requested !
   */
  if(status==SERVICE_SUCCEEDED){
    if(vid==0){
      nc = xmlNewNode(ns, BAD_CAST "ProcessOutputs");
    }
    maps* mcursor=outputs;
    elements* scursor=serv->outputs;
    map* testResponse=getMap(request,"RawDataOutput");	
    if(testResponse==NULL)
      testResponse=getMap(request,"ResponseDocument");
    while(mcursor!=NULL){		
      map* tmp0=getMap(mcursor->content,"inRequest");
      scursor=getElements(serv->outputs,mcursor->name);	  
      if(scursor!=NULL){		  
	if(testResponse==NULL || tmp0==NULL){		
	  if(vid==0)
	    printIOType(doc,nc,ns,ns_ows,ns_xlink,scursor,mcursor,"Output",vid);
	  else
	    printIOType(doc,n,ns,ns_ows,ns_xlink,scursor,mcursor,"Output",vid);
	}
	else
	  if(tmp0!=NULL && strncmp(tmp0->value,"true",4)==0){		  
	    if(vid==0)
	      printIOType(doc,nc,ns,ns_ows,ns_xlink,scursor,mcursor,"Output",vid);
	    else 
	      printIOType(doc,n,ns,ns_ows,ns_xlink,scursor,mcursor,"Output",vid);
	  }	
      }else
	/**
	 * In case there was no definition found in the ZCFG file but 
	 * present in the service code
	 */
	if(vid==0)
	  printIOType(doc,nc,ns,ns_ows,ns_xlink,scursor,mcursor,"Output",vid);
	else
	  printIOType(doc,n,ns,ns_ows,ns_xlink,scursor,mcursor,"Output",vid);
      mcursor=mcursor->next;
    }	
    if(vid==0)
      xmlAddChild(n,nc);
  }  
  if(vid==0 && 
     hasStoredExecuteResponse==true 
     && status!=SERVICE_STARTED 
#ifndef WIN32
     && status!=SERVICE_ACCEPTED
#endif
     ){
#ifndef RELY_ON_DB
    semid lid=acquireLock(pmsConf);//,1);
    if(lid<0){
      /* If the lock failed */
      errorException(&pmsConf,_("Lock failed."),"InternalError",NULL);
      xmlFreeDoc(doc);
      xmlCleanupParser();
      zooXmlCleanupNs();
      return;
    }
    else{
#endif
      /* We need to write the ExecuteResponse Document somewhere */
      FILE* output=fopen(stored_path,"w");
      if(output==NULL){
	/* If the file cannot be created return an ExceptionReport */
	char tmpMsg[1024];
	sprintf(tmpMsg,_("Unable to create the file \"%s\" for storing the ExecuteResponse."),stored_path);

	errorException(&pmsConf,tmpMsg,"InternalError",NULL);
	xmlFreeDoc(doc);
	xmlCleanupParser();
	zooXmlCleanupNs();
#ifndef RELY_ON_DB
	unlockShm(lid);
#endif
	return;
      }
      xmlChar *xmlbuff;
      int buffersize;
      xmlDocDumpFormatMemoryEnc(doc, &xmlbuff, &buffersize, "UTF-8", 1);
      fwrite(xmlbuff,1,xmlStrlen(xmlbuff)*sizeof(char),output);
      xmlFree(xmlbuff);
      fclose(output);
#ifndef RELY_ON_DB
#ifdef DEBUG
      fprintf(stderr,"UNLOCK %s %d !\n",__FILE__,__LINE__);
#endif
      unlockShm(lid);
      map* v=getMapFromMaps(pmsConf,"lenv","sid");
      // Remove the lock when running as a normal task
      if(getpid()==atoi(v->value)){
	removeShmLock (pmsConf, 1);
      }
    }
#endif
  }

  printDocument(pmsConf,doc,pid);

  xmlCleanupParser();
  zooXmlCleanupNs();
}

/**
 * Print a XML document.
 * 
 * @param m the conf maps containing the main.cfg settings
 * @param doc the XML document
 * @param pid the process identifier linked to a service
 */
void printDocument(maps* pmsConf, xmlDocPtr doc,int pid){
  char *encoding=getEncoding(pmsConf);
  if(pid==getpid()){
    printHeaders(pmsConf);
    printf("Content-Type: text/xml; charset=%s\r\nStatus: 200 OK\r\n\r\n",encoding);
  }
  xmlChar *xmlbuff;
  int buffersize;
  /*
   * Dump the document to a buffer and print it on stdout
   * for demonstration purposes.
   */
  xmlDocDumpFormatMemoryEnc(doc, &xmlbuff, &buffersize, encoding, 1);
  printf("%s",xmlbuff);
  fflush(stdout);
  /*
   * Free associated memory.
   */
  xmlFree(xmlbuff);
  xmlFreeDoc(doc);
  xmlCleanupParser();
  zooXmlCleanupNs();
}

/**
 * Print a XML document.
 * 
 * @param doc the XML document (unused)
 * @param nc the XML node to add the output definition
 * @param ns_wps the wps XML namespace
 * @param ns_ows the ows XML namespace
 * @param e the output elements 
 * @param m the conf maps containing the main.cfg settings
 * @param type the type (unused)
 */
void printOutputDefinitions(xmlDocPtr doc,xmlNodePtr nc,xmlNsPtr ns_wps,xmlNsPtr ns_ows,elements* e,maps* pmsConf,const char* type){
  xmlNodePtr nc1;
  nc1=xmlNewNode(ns_wps, BAD_CAST type);
  map *tmp=NULL;  
  if(e!=NULL && e->defaults!=NULL)
    tmp=e->defaults->content;
  else{
    /*
      dumpElements(e);
    */
    return;
  }
  while(tmp!=NULL){
    if(strncasecmp(tmp->name,"MIMETYPE",strlen(tmp->name))==0
       || strncasecmp(tmp->name,"ENCODING",strlen(tmp->name))==0
       || strncasecmp(tmp->name,"SCHEMA",strlen(tmp->name))==0
       || strncasecmp(tmp->name,"UOM",strlen(tmp->name))==0)
      xmlNewProp(nc1,BAD_CAST tmp->name,BAD_CAST tmp->value);
    tmp=tmp->next;
  }
  tmp=getMap(e->defaults->content,"asReference");
  if(tmp==NULL)
    xmlNewProp(nc1,BAD_CAST "asReference",BAD_CAST "false");

  tmp=e->content;

  printDescription(nc1,ns_ows,pmsConf->name,e->content,0);

  xmlAddChild(nc,nc1);

}

/**
 * Generate XML nodes describing inputs or outputs metadata.
 * 
 * @param doc the XML document 
 * @param nc the XML node to add the definition
 * @param ns_wps the wps namespace
 * @param ns_ows the ows namespace
 * @param ns_xlink the xlink namespace
 * @param e the output elements 
 * @param m the conf maps containing the main.cfg settings
 * @param type the type
 */
void printIOType(xmlDocPtr doc,xmlNodePtr nc,xmlNsPtr ns_wps,xmlNsPtr ns_ows,xmlNsPtr ns_xlink,elements* e,maps* pmsConf,const char* type,int vid){
  xmlNodePtr nc1,nc2,nc3;
  nc1=xmlNewNode(ns_wps, BAD_CAST type);
  map *tmp=NULL;
  if(e!=NULL)
    tmp=e->content;
  else
    tmp=pmsConf->content;
  if(vid==0){
    nc2=xmlNewNode(ns_ows, BAD_CAST "Identifier");
    if(e!=NULL)
      nc3=xmlNewText(BAD_CAST e->name);
    else
      nc3=xmlNewText(BAD_CAST pmsConf->name);

    xmlAddChild(nc2,nc3);
    xmlAddChild(nc1,nc2);

    xmlAddChild(nc,nc1);

    if(e!=NULL)
      tmp=getMap(e->content,"Title");
    else
      tmp=getMap(pmsConf->content,"Title");

    if(tmp!=NULL){
      nc2=xmlNewNode(ns_ows, BAD_CAST tmp->name);
      nc3=xmlNewText(BAD_CAST _ss(tmp->value));
      xmlAddChild(nc2,nc3);  
      xmlAddChild(nc1,nc2);
    }

    if(e!=NULL)
      tmp=getMap(e->content,"Abstract");
    else
      tmp=getMap(pmsConf->content,"Abstract");

    if(tmp!=NULL){
      nc2=xmlNewNode(ns_ows, BAD_CAST tmp->name);
      nc3=xmlNewText(BAD_CAST _ss(tmp->value));
      xmlAddChild(nc2,nc3);
      xmlAddChild(nc1,nc2);
      xmlAddChild(nc,nc1);
    }
  }else{
    xmlNewProp(nc1,BAD_CAST "id",BAD_CAST (e!=NULL?e->name:pmsConf->name));
  }

  // IO type nested outputs
  if(pmsConf->child!=NULL){
    maps* curs=pmsConf->child;
    elements* ecurs=getElements(e,(e!=NULL?e->name:pmsConf->name));
    ecurs=ecurs->child;
    while(curs!=NULL/* && ecurs!=NULL*/){
      ecurs=getElements(ecurs,(curs->name));
      map* inRequest=getMap(curs->content,"inRequest");
      if(inRequest!=NULL && strncasecmp(inRequest->value,"true",4)==0)
	printIOType(doc,nc1,ns_wps,ns_ows,ns_xlink,ecurs,curs,type,vid);
      curs=curs->next;
      ecurs=getElements(e,(e!=NULL?e->name:pmsConf->name));
      ecurs=ecurs->child;
    }
  }
  else{
    map *tmpMap=getMap(pmsConf->content,"Reference");
    if(tmpMap==NULL){
      nc2=xmlNewNode(ns_wps, BAD_CAST "Data");
      if(e!=NULL && e->format!=NULL){
	if (strncasecmp(e->format, "LiteralOutput", strlen(e->format)) == 0)
	  nc3 = xmlNewNode(ns_wps, BAD_CAST "LiteralData");
	else
	  if(strncasecmp(e->format,"ComplexOutput",strlen(e->format))==0)
	    nc3=xmlNewNode(ns_wps, BAD_CAST "ComplexData");
	  else if(strncasecmp(e->format,"BoundingBoxOutput",strlen(e->format))==0)
	    nc3=xmlNewNode(ns_wps, BAD_CAST "BoundingBoxData");
	  else
	    nc3=xmlNewNode(ns_wps, BAD_CAST e->format);
      }
      else {
	map* tmpV=getMapFromMaps(pmsConf,"format","value");
	if(tmpV!=NULL)
	  nc3=xmlNewNode(ns_wps, BAD_CAST tmpV->value);
	else
	  nc3=xmlNewNode(ns_wps, BAD_CAST "LiteralData");
      } 
      tmp=pmsConf->content;

      while(tmp!=NULL){
	if(strcasecmp(tmp->name,"mimeType")==0 ||
	   strcasecmp(tmp->name,"encoding")==0 ||
	   strcasecmp(tmp->name,"schema")==0 ||
	   strcasecmp(tmp->name,"datatype")==0 ||
	   strcasecmp(tmp->name,"uom")==0) {
	  if(vid==0)
	    xmlNewProp(nc3,BAD_CAST tmp->name,BAD_CAST tmp->value);
	  else{
	    if(strcasecmp(tmp->name,"datatype")==0){
	      if(getMap(pmsConf->content,"mimeType")==NULL)
	        xmlNewProp(nc2,BAD_CAST "mimeType",BAD_CAST "text/plain");
	    }
	    else
	      if(strcasecmp(tmp->name,"uom")!=0)
		xmlNewProp(nc2,BAD_CAST tmp->name,BAD_CAST tmp->value);
	  }
	}

	if(vid==0)
	  xmlAddChild(nc2,nc3);
	tmp=tmp->next;	
      }
      if(e!=NULL && e->format!=NULL && strcasecmp(e->format,"BoundingBoxData")==0) {
	map* bb=getMap(pmsConf->content,"value");
	if(bb!=NULL) {
	  map* tmpRes=parseBoundingBox(bb->value);
	  printBoundingBox(ns_ows,nc3,tmpRes);
	  freeMap(&tmpRes);
	  free(tmpRes);
	}
      }
      else {
		  //if (e != NULL) {
		  if (e != NULL && e->defaults != NULL) { // knut: add extra NULL pointer check in case user omits <Default> block in config file			  
			  tmp = getMap(e->defaults->content, "mimeType");
		  }
	else
	  tmp=NULL;	
	map* tmp1=getMap(pmsConf->content,"encoding");
	map* tmp2=getMap(pmsConf->content,"mimeType");
	map* tmp3=getMap(pmsConf->content,"value");
	int hasValue=1;
	if(tmp3==NULL){
	  tmp3=createMap("value","");
	  hasValue=-1;
	}

	if( ( tmp1 != NULL && strncmp(tmp1->value,"base64",6) == 0 )     // if encoding is base64
	    || 	                                                       // or if 
	    ( tmp2 != NULL && ( strstr(tmp2->value,"text") == NULL       //  mime type is not text 
				&&                                       //  nor 
				strstr(tmp2->value,"xml") == NULL        //  xml
				&&                                       // nor
				strstr(tmp2->value,"javascript") == NULL // javascript
				&&
				strstr(tmp2->value,"json") == NULL
				&&
				strstr(tmp2->value,"ecmascript") == NULL
				&&
				// include for backwards compatibility,
				// although correct mime type is ...kml+xml:
				strstr(tmp2->value,"google-earth.kml") == NULL							)
	      )
	    ) { 	                                                 // then	
	  map* rs=getMap(pmsConf->content,"size");                       // obtain size
	  bool isSized=true;
	  if(rs==NULL){
	    char tmp1[1024];
	    sprintf(tmp1,"%ld",strlen(tmp3->value));
	    rs=createMap("size",tmp1);
	    isSized=false;
	  }

	  xmlAddChild((vid==0?nc3:nc2),xmlNewText(BAD_CAST base64(tmp3->value, atoi(rs->value))));  // base 64 encode in XML

	  if(tmp1==NULL || (tmp1!=NULL && strncmp(tmp1->value,"base64",6)!=0)) {
	    xmlAttrPtr ap = xmlHasProp((vid==0?nc3:nc2), BAD_CAST "encoding");
	    if (ap != NULL) {
	      xmlRemoveProp(ap);
	    }			
	    xmlNewProp((vid==0?nc3:nc2),BAD_CAST "encoding",BAD_CAST "base64");
	  }

	  if(!isSized){
	    freeMap(&rs);
	    free(rs);
	  }
	}
	else if (tmp2!=NULL) {                                 // else (text-based format) 
	  if(strstr(tmp2->value, "javascript") != NULL ||      //    if javascript put code in CDATA block 
	     strstr(tmp2->value, "json") != NULL ||            //    (will not be parsed by XML reader) 
	     strstr(tmp2->value, "ecmascript") != NULL
	     ) {
	    xmlAddChild((vid==0?nc3:nc2),xmlNewCDataBlock(doc,BAD_CAST tmp3->value,strlen(tmp3->value)));
	  }   
	  else {                                                     // else
	    if (strstr(tmp2->value, "xml") != NULL ||                 // if XML-based format
		// include for backwards compatibility,
		// although correct mime type is ...kml+xml:		   
		strstr(tmp2->value, "google-earth.kml") != NULL
		) { 

	      int li=zooXmlAddDoc(tmp3->value);
	      xmlDocPtr doc = iDocs[li];
	      xmlNodePtr ir = xmlDocGetRootElement(doc);
	      xmlAddChild((vid==0?nc3:nc2),ir);
	    }
	    else                                                     // else	
	      xmlAddChild((vid==0?nc3:nc2),xmlNewText(BAD_CAST tmp3->value));    //   add text node
	  }
	  if(vid==0)
	    xmlAddChild(nc2,nc3);
	}
	else {
	  xmlAddChild((vid==0?nc3:nc2),xmlNewText(BAD_CAST tmp3->value));
	}

	if(hasValue<0) {
	  freeMap(&tmp3);
	  free(tmp3);
	}
      }
    }
    else { // Reference
      tmpMap=getMap(pmsConf->content,"Reference");
      nc3=nc2=xmlNewNode(ns_wps, BAD_CAST "Reference");
      /* Special case to avoid failing to validate against the WPS 2.0 schema */
      if(strcasecmp(type,"Output")==0 && vid==0)
	xmlNewProp(nc3,BAD_CAST "href",BAD_CAST tmpMap->value);
      else
	xmlNewNsProp(nc3,ns_xlink,BAD_CAST "href",BAD_CAST tmpMap->value);

      tmp=pmsConf->content;
      while(tmp!=NULL) {
	if(strcasecmp(tmp->name,"mimeType")==0 ||
	   strcasecmp(tmp->name,"encoding")==0 ||
	   strcasecmp(tmp->name,"schema")==0 ||
	   strcasecmp(tmp->name,"datatype")==0 ||
	   strcasecmp(tmp->name,"uom")==0){

          if(strcasecmp(tmp->name,"datatype")==0){
            if(getMap(pmsConf->content,"mimeType")==NULL){
              xmlNewProp(nc3,BAD_CAST "mimeType",BAD_CAST "text/plain");
	    }
          }
	  else
	    xmlNewProp(nc3,BAD_CAST tmp->name,BAD_CAST tmp->value);
	}
	tmp=tmp->next;
	xmlAddChild(nc2,nc3);
      }
    }
    xmlAddChild(nc1,nc2);
  }
  xmlAddChild(nc,nc1);
}

/**
 * Create XML node with basic ows metadata information (Identifier,Title,Abstract)
 *
 * @param root the root XML node to add the description
 * @param ns_ows the ows XML namespace
 * @param identifier the identifier to use
 * @param amap the map containing the ows metadata information 
 */
void printDescription(xmlNodePtr root,xmlNsPtr ns_ows,const char* identifier,map* amap,int vid=0){
  xmlNodePtr nc2;
  if(vid==0){
    nc2 = xmlNewNode(ns_ows, BAD_CAST "Identifier");
    xmlAddChild(nc2,xmlNewText(BAD_CAST identifier));
    xmlAddChild(root,nc2);
  }
  map* tmp=amap;
  const char *tmp2[2];
  tmp2[0]="Title";
  tmp2[1]="Abstract";
  int j=0;
  for(j=0;j<2;j++){
    map* tmp1=getMap(tmp,tmp2[j]);
    if(tmp1!=NULL){
      nc2 = xmlNewNode(ns_ows, BAD_CAST tmp2[j]);
      xmlAddChild(nc2,xmlNewText(BAD_CAST _ss(tmp1->value)));
      xmlAddChild(root,nc2);
    }
  }
  if(vid==1){
    nc2 = xmlNewNode(ns_ows, BAD_CAST "Identifier");
    xmlAddChild(nc2,xmlNewText(BAD_CAST identifier));
    xmlAddChild(root,nc2);
  }
}

/**
 * Produce the status string used in HTTP headers.
 * 
 * @param pmConf the maps containing the settings of the main.cfg file
 * @param pmCode the map containing the error code (or a map array of the same keys)
 */
const char* produceStatusString(maps* pmConf,map* pmCode){
  if(pmCode!=NULL){
    int iI=0;
    for(iI=0;iI<3;iI++){
      int iJ=0;
      for(iJ=1;;iJ++){
        if(aapccStatusCodes[iI][iJ]==NULL)
          break;
        else{
          if(strcmp(aapccStatusCodes[iI][iJ],pmCode->value)==0)
            return aapccStatusCodes[iI][0];
        }
      }
    }
  }
  else{
    return aapccStatusCodes[3][0];
  }
  return aapccStatusCodes[3][0];
}

/**
 * Print an OWS ExceptionReport Document and HTTP headers (when required) 
 * depending on the code.
 * Set hasPrinted value to true in the [lenv] section.
 * 
 * @param m the maps containing the settings of the main.cfg file
 * @param s the map containing the text,code,locator keys (or a map array of the same keys)
 */
void _printExceptionReportResponse(maps* pmsConf,map* s){
  int buffersize;
  xmlDocPtr doc;
  xmlChar *xmlbuff;
  xmlNodePtr n;

  zooXmlCleanupNs();
  doc = xmlNewDoc(BAD_CAST "1.0");
  maps* tmpMap=getMaps(pmsConf,"main");
  char *encoding=getEncoding(tmpMap);
  const char *exceptionCode;

  map* tmp=getMap(s,"code");
  exceptionCode=produceStatusString(pmsConf,tmp);
  tmp=getMapFromMaps(pmsConf,"lenv","status_code");
  if(tmp!=NULL)
    exceptionCode=tmp->value;
  if(exceptionCode==NULL)
    exceptionCode=aapccStatusCodes[3][0];
  if(pmsConf!=NULL){
    map *tmpSid=getMapFromMaps(pmsConf,"lenv","sid");
    if(tmpSid!=NULL){
      if( getpid()==atoi(tmpSid->value) ){
        printHeaders(pmsConf);
        printf("Content-Type: text/xml; charset=%s\r\nStatus: %s\r\n\r\n",encoding,exceptionCode);
      }
    }
    else{
      printHeaders(pmsConf);
      printf("Content-Type: text/xml; charset=%s\r\nStatus: %s\r\n\r\n",encoding,exceptionCode);
    }
  }else{
    printf("Content-Type: text/xml; charset=%s\r\nStatus: %s\r\n\r\n",encoding,exceptionCode);
  }
  n=createExceptionReportNode(pmsConf,s,1);
  xmlDocSetRootElement(doc, n);
  xmlDocDumpFormatMemoryEnc(doc, &xmlbuff, &buffersize, encoding, 1);
  printf("%s",xmlbuff);
  fflush(stdout);
  xmlFreeDoc(doc);
  xmlFree(xmlbuff);
  xmlCleanupParser();
  zooXmlCleanupNs();
  if(pmsConf!=NULL)
    setMapInMaps(pmsConf,"lenv","hasPrinted","true");
}

/**
 * Print an OWS ExceptionReport or exception.yaml Document and HTTP headers
 * (when required) depending on the code.
 * 
 * @param pmsConf the maps containing the settings of the main.cfg file
 * @param pmError the map containing the text,code,locator keys (or a map array)
 */
void printExceptionReportResponse(maps** pmsConf,map* pmError){
  if(getMapFromMaps(*pmsConf,"lenv","hasPrinted")!=NULL)
    return;
  map* pmExecutionType=getMapFromMaps(*pmsConf,"main","executionType");
  if(pmExecutionType!=NULL && strncasecmp(pmExecutionType->value,"xml",3)==0)
    _printExceptionReportResponse(*pmsConf,pmError);
  else
    printExceptionReportResponseJ(pmsConf,pmError);
}

/**
 * Create an OWS ExceptionReport Node.
 * 
 * @param m the conf maps
 * @param s the map containing the text,code,locator keys
 * @param use_ns (0/1) choose if you want to generate an ExceptionReport or 
 *  ows:ExceptionReport node respectively
 * @return the ExceptionReport/ows:ExceptionReport node
 */
xmlNodePtr createExceptionReportNode(maps* pmsConf,map* s,int use_ns){

  xmlNsPtr ns,ns_xsi;
  xmlNodePtr n,nc,nc1;

  int nsid=zooXmlAddNs(NULL,"http://www.opengis.net/ows","ows");
  ns=usedNs[nsid];
  if(use_ns==0){
    ns=NULL;
  }
  n = xmlNewNode(ns, BAD_CAST "ExceptionReport");
  map* version=getMapFromMaps(pmsConf,"main","rversion");
  int vid=-1;
  if(version!=NULL)
    vid=getVersionId(version->value);
  if(vid<0)
    vid=0;
  if(use_ns==1){
    xmlNewNs(n,BAD_CAST schemas[vid][1],BAD_CAST"ows");
    int xsiId=zooXmlAddNs(n,"http://www.w3.org/2001/XMLSchema-instance","xsi");
    ns_xsi=usedNs[xsiId];
    char tmp[1024];
    sprintf(tmp,"%s %s",schemas[vid][1],schemas[vid][5]);
    xmlNewNsProp(n,ns_xsi,BAD_CAST "schemaLocation",BAD_CAST tmp);
  }


  addLangAttr(n,pmsConf);
  xmlNewProp(n,BAD_CAST "version",BAD_CAST schemas[vid][6]);

  int length=1;
  int cnt=0;
  map* len=getMap(s,"length");
  if(len!=NULL)
    length=atoi(len->value);
  for(cnt=0;cnt<length;cnt++){
    nc = xmlNewNode(ns, BAD_CAST "Exception");

    map* tmp=getMapArray(s,"code",cnt);
    if(tmp==NULL)
      tmp=getMap(s,"code");
    if(tmp!=NULL)
      xmlNewProp(nc,BAD_CAST "exceptionCode",BAD_CAST tmp->value);
    else
      xmlNewProp(nc,BAD_CAST "exceptionCode",BAD_CAST "NoApplicableCode");

    tmp=getMapArray(s,"locator",cnt);
    if(tmp==NULL)
      tmp=getMap(s,"locator");
    if(tmp!=NULL && strcasecmp(tmp->value,"NULL")!=0)
      xmlNewProp(nc,BAD_CAST "locator",BAD_CAST tmp->value);

    tmp=getMapArray(s,"text",cnt);
    if(tmp==NULL)
      tmp=getMapArray(s,"message",cnt);
    nc1 = xmlNewNode(ns, BAD_CAST "ExceptionText");
    if(tmp!=NULL){
      xmlNodePtr txt=xmlNewText(BAD_CAST tmp->value);
      xmlAddChild(nc1,txt);
      if(cnt==0)
        setMapInMaps(pmsConf,"lenv","message",tmp->value);
    }
    else{
      xmlNodeSetContent(nc1, BAD_CAST _("No debug message available"));
    }
    xmlAddChild(nc,nc1);
    xmlAddChild(n,nc);
  }
  return n;
}


/**
 * Invoke the ensureFiltered then printExceptionReportResponseJ functions
 *
 * @param pmsConf the maps containing the settings of the main.cfg file
 * @param pmError the map containing the text,code,locator keys (or a map array)
 * @see printExceptionReportResponseJ,ensureFiltered
 */
void localPrintException(maps** pmsConf,map* pmError){
  map* pmTrace=getMapFromMaps(*pmsConf,"lenv","trace");
  if(pmTrace==NULL || (pmTrace!=NULL && strcasecmp(pmTrace->value,"true"))!=0)
    ensureFiltered(pmsConf,"out");
  map* pmExecutionType=getMapFromMaps(*pmsConf,"main","executionType");
  if(pmExecutionType!=NULL && strcasecmp(pmExecutionType->value,"json")==0)
    printExceptionReportResponseJ(pmsConf,pmError);
  else
    printExceptionReportResponse(pmsConf,pmError);
}

/**
 * Print an OWS ExceptionReport.
 *
 * @param pmsConf the conf maps
 * @param message the error message
 * @param errorcode the error code
 * @param locator the potential locator
 */
int errorException(maps **pmsConf, const char *message, const char *errorcode, const char *locator)
{
  map* pmExectionType=getMapFromMaps(*pmsConf,"main","executionType");
  map* errormap = createMap("text", message);
  addToMap(errormap,"code", errorcode);
  if(locator!=NULL)
    addToMap(errormap,"locator", locator);
  else
    addToMap(errormap,"locator", "NULL");
  if(pmExectionType!=NULL && strncasecmp(pmExectionType->value,"xml",3)==0)
    localPrintException(pmsConf,errormap);
  else{
    localPrintException(pmsConf,errormap);
    setMapInMaps(*pmsConf,"lenv","no-headers","true");
  }
#ifdef LOG_CONSOLE_ENABLED
    logConsoleMessage(message);
#endif
  freeMap(&errormap);
  free(errormap);
  return -1;
}

/**
 * Produce a copy file and the corresponding url in case it is required
 * Please, free the returned ressource while used
 *
 * @param pmConf maps* pointing to the main configuration file
 */
char* produceFileUrl(service* psService,maps* pmsConf,maps* pmsOutputs,const char* pccFormat, int itn){
  // Create file for reference data if not existing
  map *pmGFile=getMap(pmsOutputs->content,"generated_file");
  map *pmTmpPath=getMapFromMaps(pmsConf,"main","tmpPath");
  map *pmTmpUrl=getMapFromMaps(pmsConf,"main","tmpUrl");
  char *pcaFileName=NULL;
  char *pcaFilePath=NULL;
  char *pcaFileUrl=NULL;
  if(pmGFile!=NULL){
    pmGFile=getMap(pmsOutputs->content,"expected_generated_file");
    if(pmGFile==NULL){
      pmGFile=getMap(pmsOutputs->content,"generated_file");
    }
    if(strstr(pmGFile->value,pmTmpPath->value)!=NULL)
      pcaFileName=zStrdup(strstr(pmGFile->value,pmTmpPath->value)+strlen(pmTmpPath->value));
  }
  // Create file for reference data
  map *pmUsid=getMapFromMaps(pmsConf,"lenv","usid");
  map *pmExt=getMap(pmsOutputs->content,"extension");
  if(pmGFile==NULL){
    char acFileExt[32];	    
    if( pmExt != NULL && pmExt->value != NULL) {
      strncpy(acFileExt, pmExt->value, 32);
    }
    else {
      // Obtain default file extension (see mimetypes.h).	      
      // If the MIME type is not recognized, txt is used as the default extension
      map* pmType=getMap(pmsOutputs->content,"mimeType");
      getFileExtension(pmType != NULL ? pmType->value : NULL, acFileExt, 32);
    }
    if(pcaFileName!=NULL)
      free(pcaFileName);

    pcaFileName=(char*)malloc((strlen(psService->name)+strlen(pmUsid->value)+strlen(acFileExt)+strlen(pmsOutputs->name)+45)*sizeof(char));
    sprintf(pcaFileName,"ZOO_DATA_%s_%s_%s_%d.%s",psService->name,pmsOutputs->name,pmUsid->value,itn,acFileExt);

    pcaFilePath=(char*)malloc((strlen(pmTmpPath->value)+strlen(pcaFileName)+2)*sizeof(char));
    sprintf(pcaFilePath,"%s/%s",pmTmpPath->value,pcaFileName);
  }else{
    pcaFilePath=(char*)malloc((strlen(pmGFile->value)+1)*sizeof(char));
    sprintf(pcaFilePath,"%s",pmGFile->value);
  }

  pcaFileUrl=(char*)malloc((strlen(pmTmpUrl->value)+
			  strlen(pcaFileName)+2)*sizeof(char));
  sprintf(pcaFileUrl,"%s/%s",pmTmpUrl->value,pcaFileName);

  if(pmGFile==NULL) {
    FILE *pfOfile=fopen(pcaFilePath,"wb");
    if(pfOfile==NULL){
      char acTmpMsg[1024];
      sprintf(acTmpMsg,
	      _("Unable to create the file \"%s\" for storing the %s final result."),
	      pcaFileName,pmsOutputs->name);
      map* pmError=createMap("code","InternalError");
      addToMap(pmError,"message",acTmpMsg);
      printExceptionReportResponseJ(&pmsConf,pmError);
      free(pcaFileName);
      free(pcaFilePath);
      return NULL;
    }

    map* pmValue=getMap(pmsOutputs->content,"value");
    if(pmValue==NULL){
      char acTmpMsg[1024];
      sprintf(acTmpMsg,
	      _("No value found for the requested output %s."),
	      pmsOutputs->name);
      map* pmError=createMap("code","InternalError");
      addToMap(pmError,"message",acTmpMsg);
      printExceptionReportResponseJ(&pmsConf,pmError);
      fclose(pfOfile);
      free(pcaFileName);
      free(pcaFilePath);
      return NULL;
    }
    if(pccFormat==NULL || strcasecmp(pccFormat,"BoundingBoxData")!=0){
      map* size=getMap(pmsOutputs->content,"size");
      if(size!=NULL && pmValue!=NULL)
        fwrite(pmValue->value,1,(atoi(size->value))*sizeof(char),pfOfile);
      else
        if(pmValue!=NULL && pmValue->value!=NULL)
          fwrite(pmValue->value,1,
          strlen(pmValue->value)*sizeof(char),pfOfile);
    }else
      printBoundingBoxDocument(pmsConf,pmsOutputs,pfOfile);
    fclose(pfOfile);
  }
  free(pcaFileName);
  free(pcaFilePath);
  return pcaFileUrl;
}

/**
 * Generate the output response (RawDataOutput or ResponseDocument)
 *
 * @param s the service structure containing the metadata information
 * @param request_inputs the inputs provided to the service for execution
 * @param request_outputs the outputs updated by the service execution
 * @param request_inputs1 the map containing the HTTP request
 * @param cpid the process identifier attached to a service execution
 * @param pmsConf the conf maps containing the main.cfg settings
 * @param res the value returned by the service execution
 */
void outputResponse(service* s,maps* request_inputs,maps* request_outputs,
		    map* request_inputs1,int cpid,maps* pmsConf,int res){
#ifdef DEBUG
  dumpMaps(request_inputs);
  dumpMaps(request_outputs);
  fprintf(stderr,"printProcessResponse\n");
#endif  
  map* pmRawData=getMap(request_inputs1,"RawDataOutput");
  int asRaw=0;
  if(pmRawData!=NULL)
    asRaw=1;
  map* version=getMapFromMaps(pmsConf,"main","rversion");
  int vid=getVersionId(version->value);
  printSessionHeaders(pmsConf);
  if(res==SERVICE_FAILED){
    char* tmp0=produceErrorMessage(pmsConf);
    errorException(&pmsConf,tmp0,"InternalError",NULL);
    free(tmp0);
    return;
  }

  if(res==SERVICE_ACCEPTED && vid==1){
    map* statusInfo=createMap("Status","Accepted");
    map *usid=getMapFromMaps(pmsConf,"lenv","usid");
    addToMap(statusInfo,"JobID",usid->value);
    printStatusInfo(pmsConf,statusInfo,(char*)"Execute");
    freeMap(&statusInfo);
    free(statusInfo);
    return;
  }

  if(res!=SERVICE_SUCCEEDED){	  
    printProcessResponse(pmsConf,request_inputs1,cpid,
                         s, s->name,res,  // replace serviceProvider with serviceName in stored response file name
                         request_inputs,
                         request_outputs);
    return;
  }

  map *tmp1=getMapFromMaps(pmsConf,"main","tmpPath");
  if(asRaw==0){
#ifdef DEBUG
    fprintf(stderr,"REQUEST_OUTPUTS FINAL\n");
    dumpMaps(request_outputs);
#endif
    maps* tmpI=request_outputs;
    maps* stmpI=NULL;
    map* usid=getMapFromMaps(pmsConf,"lenv","usid");
    int itn=0;
    int error=-1;
  NESTED0:
    while(tmpI!=NULL){
      if(tmpI->child!=NULL){
        stmpI=tmpI;
        tmpI=tmpI->child;
      }
#ifdef USE_MS
      map* testMap=getMap(tmpI->content,"useMapserver");	
#endif
      /*map *gfile=getMap(tmpI->content,"generated_file");
      char *file_name=NULL;	  
      if(gfile!=NULL){
	gfile=getMap(tmpI->content,"expected_generated_file");
	if(gfile==NULL){
	  gfile=getMap(tmpI->content,"generated_file");
	}
	readGeneratedFile(pmsConf,tmpI->content,gfile->value);
	file_name=zStrdup((gfile->value)+strlen(tmp1->value));
	}*/
      char *pcaFileUrl=NULL;
      pmRawData=getMap(tmpI->content,"asReference");
#ifdef USE_MS
      map* geodatatype=getMap(tmpI->content,"geodatatype");
      if(pmRawData!=NULL && strcasecmp(pmRawData->value,"true")==0 &&
        (testMap==NULL ||
          strncasecmp(testMap->value,"true",4)!=0 ||
          (geodatatype!=NULL && strcasecmp(geodatatype->value,"other")==0) ) ) 
#else
      if(pmRawData!=NULL && strcasecmp(pmRawData->value,"true")==0)
#endif
      {
        elements* in=getElements(s->outputs,tmpI->name);
        if(in==NULL && s->outputs->child!=NULL){
          in=getElements(s->outputs->child,tmpI->name);
        }
        char *format=NULL;
        if(in!=NULL && in->format!=NULL){
          format=in->format;
        }else
          format=(char*)"LiteralData";
        if(format!=NULL && strcasecmp(format,"BoundingBoxData")==0){
          addToMap(tmpI->content,"extension","xml");
          addToMap(tmpI->content,"mimeType","text/xml");
          addToMap(tmpI->content,"encoding","UTF-8");
          addToMap(tmpI->content,"schema","http://schemas.opengis.net/ows/1.1.0/owsCommon.xsd");
        }
        pcaFileUrl=produceFileUrl(s,pmsConf,tmpI,format,itn);
        itn++;
        if(pcaFileUrl==NULL)
          return;
        addToMap(tmpI->content,"Reference",pcaFileUrl);
      }
#ifdef USE_MS
      else{
        if(testMap!=NULL){
          map* nbFeatures;
          setMapInMaps(pmsConf,"lenv","state","out");
          setReferenceUrl(pmsConf,tmpI);
          nbFeatures=getMap(tmpI->content,"nb_features");
          geodatatype=getMap(tmpI->content,"geodatatype");
          if((nbFeatures!=NULL && atoi(nbFeatures->value)==0) ||
            (geodatatype!=NULL && strcasecmp(geodatatype->value,"other")==0)){
            error=1;
            res=SERVICE_FAILED;
          }
        }
      }
#endif	
      if(pcaFileUrl!=NULL){
        free(pcaFileUrl);
        pcaFileUrl=NULL;
      }
      tmpI=tmpI->next;
    }
    if(stmpI!=NULL){
      tmpI=stmpI->next;
      stmpI=NULL;
      if(tmpI!=NULL)
        goto NESTED0;
    }    
#ifdef DEBUG
    fprintf(stderr,"SERVICE : %s\n",s->name);
    dumpMaps(pmsConf);
#endif	
    if(error<0)
      printProcessResponse(pmsConf,request_inputs1,cpid,
            s, s->name,res,  // replace serviceProvider with serviceName in stored response file name
            request_inputs,
            request_outputs);
    else{
      maps* tmpMaps=getMaps(pmsConf,"lenv");
#ifdef USE_CALLBACK
      invokeCallback(pmsConf,NULL,NULL,7,0);
#endif
      printExceptionReportResponse(&pmsConf,tmpMaps->content);
    }
  }
  else{
    /**
     * We get the requested output or fallback to the first one if the 
     * requested one is not present in the resulting outputs maps.
     */
    maps* tmpI=NULL;
    map* tmpIV=getMap(request_inputs1,"RawDataOutput");
    if(tmpIV!=NULL){
      tmpI=getMaps(request_outputs,tmpIV->value);	  
    }
    if(tmpI==NULL)
      tmpI=request_outputs;

    elements* e=getElements(s->outputs,tmpI->name);
    if(e!=NULL && strcasecmp(e->format,"BoundingBoxData")==0){
      printBoundingBoxDocument(pmsConf,tmpI,NULL);
    }else{
      printRawdataOutput(pmsConf,tmpI);
    }
  }
}

/**
 * Get the number of outputs provided in the execute request body.
 *
 * @param conf the main configuration
 * @param outputs the outputs to count
 */
int getNumberOfOutputs(maps* conf,maps* outputs){
  int res=0;
  maps* pmsOut=outputs;
  while(pmsOut!=NULL){
    map* pmTmp=getMap(pmsOut->content,"inRequest");
    if(pmTmp!=NULL && strcmp(pmTmp->value,"true")==0)
      res++;
    pmsOut=pmsOut->next;
  }
  return res;
}

/**
 * Print all outputs as raw
 *
 * @param pmsConf the main configuration maps
 * @param outputs the output to be print as raw
 */
void printRawdataOutputs(maps* pmsConf,service* s,maps* outputs){
  maps* pmsOut=outputs;
  if(pmsOut!= NULL && pmsOut->next!=NULL && getNumberOfOutputs(pmsConf,outputs)>1){
    map* pmUsid=getMapFromMaps(pmsConf,"lenv","usid");
    char* pcaBoundary=(char*)malloc(strlen(pmUsid->value)+2+1);
    sprintf(pcaBoundary,"--%s",pmUsid->value);
    map* mi=getMap(pmsOut->content,"mimeType");
    if(mi!=NULL)
      printf("Content-Type: Multipart/Related; boundary=\"%s\"; type=%s; start=%s\r\nStatus: 200 OK\r\n\r\n",pcaBoundary,mi->value,pmsOut->name);
    else
      printf("Content-Type: Multipart/Related; boundary=\"%s\"; type=text/plain; start=%s\r\nStatus: 200 OK\r\n\r\n",pcaBoundary,pmsOut->name);
    int itn=0;
    while(pmsOut!=NULL){
      map* pmPresence=getMap(pmsOut->content,"inRequest");
      if(pmPresence!=NULL && strcmp(pmPresence->value,"true")==0){
        mi=getMap(pmsOut->content,"mimeType");
        printf("--%s\r\n",pcaBoundary);
        printf("Content-ID: %s\r\n",pmsOut->name);
        map* pmDescription=getMap(pmsOut->content,"abstract");
        if(pmDescription==NULL)
          pmDescription=getMap(pmsOut->content,"title");
        if(pmDescription!=NULL)
          printf("Content-Description: %s\r\n",pmDescription->value);

        char mime[1024];
        map* en=getMap(outputs->content,"encoding");
        if(mi!=NULL && en!=NULL)
          sprintf(mime,
            "Content-Type: %s; charset=%s\r\n",
            mi->value,en->value);
        else
          if(mi!=NULL)
            sprintf(mime,
              "Content-Type: %s; charset=UTF-8\r\n",
              mi->value);
          else
            sprintf(mime,"Content-Type: text/plain; charset=utf-8\r\nStatus: 200 OK\r\n\r\n");
        map* pmTransmissionMode=getMap(pmsOut->content,"transmissionMode");
        if(pmTransmissionMode==NULL)
          pmTransmissionMode=getMap(pmsOut->content,"transmission");
        if(pmTransmissionMode!=NULL && strcasecmp(pmTransmissionMode->value,"reference")==0){
          char *pcaFileUrl=produceFileUrl(s,pmsConf,pmsOut,NULL,itn);
          printf("%s",mime);
          printf("Content-Location: %s\r\n",pcaFileUrl);
          itn++;
        }else{
          map *gfile=getMap(pmsOut->content,"generated_file");
          if(gfile!=NULL){
            gfile=getMap(pmsOut->content,"expected_generated_file");
            if(gfile==NULL){
              gfile=getMap(pmsOut->content,"generated_file");
            }
            readGeneratedFile(pmsConf,pmsOut->content,gfile->value);
          }
          map* pmValue=getMap(pmsOut->content,"value");
          if(pmValue==NULL){
            char tmpMsg[1024];
            sprintf(tmpMsg,_("Wrong RawDataOutput parameter: unable to fetch any result for the given parameter name: \"%s\"."),outputs->name);
            map* pmExecutionType=getMapFromMaps(pmsConf,"main","executionType");
            if(pmExecutionType!=NULL && strncasecmp(pmExecutionType->value,"xml",3)==0)
              errorException(&pmsConf,tmpMsg,"InvalidParameterValue","RawDataOutput");
            else{
              setMapInMaps(pmsConf,"lenv","error","true");
              setMapInMaps(pmsConf,"lenv","code","InvalidParameterValue");
              setMapInMaps(pmsConf,"lenv","message",tmpMsg);
            }
            return ;
          }
          printf("%s",mime);
          map* rs=getMap(pmsOut->content,"size");
          map* fname=getMap(pmsOut->content,"filename");
          if(fname!=NULL)
            printf("Content-Disposition: attachment; filename=\"%s\"\r\n",fname->value);
          else
            printf("Content-Disposition: INLINE\r\n");
          if(rs!=NULL)
            fwrite(pmValue->value,sizeof(char),atoi(rs->value),stdout);
          else
            fwrite(pmValue->value,sizeof(char),strlen(pmValue->value),stdout);
        }
      }
      pmsOut=pmsOut->next;
    }
    printf("--%s--\r\n",pcaBoundary);
  }
  else printRawdataOutput(pmsConf,outputs);
}

/**
 * Print one outputs as raw
 * 
 * @param pmsConf the main configuration maps
 * @param outputs the output to be print as raw
 */
void printRawdataOutput(maps* pmsConf,maps* outputs){
  map *gfile=getMap(outputs->content,"generated_file");
  if(gfile!=NULL){
    gfile=getMap(outputs->content,"expected_generated_file");
    if(gfile==NULL){
      gfile=getMap(outputs->content,"generated_file");
    }
    readGeneratedFile(pmsConf,outputs->content,gfile->value);
  }
  map* toto=getMap(outputs->content,"value");
  if(toto==NULL){
    char tmpMsg[1024];
    sprintf(tmpMsg,_("Wrong RawDataOutput parameter: unable to fetch any result for the given parameter name: \"%s\"."),outputs->name);
    map* pmExecutionType=getMapFromMaps(pmsConf,"main","executionType");
    if(pmExecutionType!=NULL && strncasecmp(pmExecutionType->value,"xml",3)==0)
      errorException(&pmsConf,tmpMsg,"InvalidParameterValue","RawDataOutput");
    else{
      setMapInMaps(pmsConf,"lenv","error","true");
      setMapInMaps(pmsConf,"lenv","code","InvalidParameterValue");
      setMapInMaps(pmsConf,"lenv","message",tmpMsg);
    }
    return ;
  }
  map* pmHeaders=getMapFromMaps(pmsConf,"lenv","no-headers");
  map* rs=getMapFromMaps(outputs,outputs->name,"size");
  if(pmHeaders==NULL || strncasecmp(pmHeaders->value,"false",5)==0){
    if(rs!=NULL)
      printf("Content-Length: %s\r\n",rs->value);
    char* pcaMimeType=NULL;
    map* mi=getMap(outputs->content,"mimeType");
    map* en=getMap(outputs->content,"encoding");
    if(mi!=NULL && en!=NULL){
      pcaMimeType=(char*)malloc((strlen(mi->value)+strlen(en->value)+30)*sizeof(char));
      sprintf(pcaMimeType,
	      "Content-Type: %s; charset=%s\r\n",
	      mi->value,en->value);
    }
    else
      if(mi!=NULL){
        pcaMimeType=(char*)malloc((strlen(mi->value)+32)*sizeof(char));
        sprintf(pcaMimeType,
          "Content-Type: %s; charset=UTF-8\r\n",
          mi->value);
      }
      else{
        pcaMimeType=(char*)malloc(42*sizeof(char));
        sprintf(pcaMimeType,"Content-Type: text/plain; charset=utf-8\r\n");
      }
    printf("%s",pcaMimeType);
    free(pcaMimeType);
    // checking if the deploy service has returned the service id
    // if it did we add the service url to the location header
    map* location = getMapFromMaps(pmsConf,"lenv","deployedServiceId");
    if(location!=NULL){
      map* rootUrl=getMapFromMaps(pmsConf,"openapi","rootUrl");
      char* locationUrlHeader=NULL;
      locationUrlHeader=(char*)malloc((strlen(rootUrl->value)+strlen(location->value)+12)*sizeof(char));
      sprintf(locationUrlHeader,"%s/processes/%s",rootUrl->value,location->value);
      printf("Location: %s\r\n",locationUrlHeader);
    }
    printHeaders(pmsConf);
    map* pmStatus = getMapFromMaps(pmsConf,"headers","Status");
    if(pmStatus!=NULL){
      printf("Status: %s;\r\n\r\n",pmStatus->value);
    } else {
      printf("Status: 200 OK;\r\n\r\n");
    }
  }


  if(rs!=NULL)
    fwrite(toto->value,1,atoi(rs->value),stdout);
  else
    fwrite(toto->value,1,strlen(toto->value),stdout);
  fflush(stdout);
}

/**
 * Create required XML nodes for boundingbox and update the current XML node
 *
 * @param ns_ows the ows XML namespace
 * @param n the XML node to update
 * @param boundingbox the map containing the boundingbox definition
 */
void printBoundingBox(xmlNsPtr ns_ows,xmlNodePtr n,map* boundingbox){

  xmlNodePtr lw=NULL,uc=NULL;

  map* tmp=getMap(boundingbox,"value");

  tmp=getMap(boundingbox,"lowerCorner");
  if(tmp!=NULL){
    lw=xmlNewNode(ns_ows,BAD_CAST "LowerCorner");
    xmlAddChild(lw,xmlNewText(BAD_CAST tmp->value));
  }

  tmp=getMap(boundingbox,"upperCorner");
  if(tmp!=NULL){
    uc=xmlNewNode(ns_ows,BAD_CAST "UpperCorner");
    xmlAddChild(uc,xmlNewText(BAD_CAST tmp->value));
  }

  tmp=getMap(boundingbox,"crs");
  if(tmp!=NULL)
    xmlNewProp(n,BAD_CAST "crs",BAD_CAST tmp->value);

  tmp=getMap(boundingbox,"dimensions");
  if(tmp!=NULL)
    xmlNewProp(n,BAD_CAST "dimensions",BAD_CAST tmp->value);

  xmlAddChild(n,lw);
  xmlAddChild(n,uc);

}

/**
 * Parse a BoundingBox string
 *
 * [OGC 06-121r3](http://portal.opengeospatial.org/files/?artifact_id=20040):
 *  10.2 Bounding box
 * 
 *
 * Value is provided as : lowerCorner,upperCorner,crs,dimension
 * Exemple : 189000,834000,285000,962000,urn:ogc:def:crs:OGC:1.3:CRS84
 *
 * A map to store boundingbox information should contain:
 *  - lowerCorner : double,double (minimum within this bounding box)
 *  - upperCorner : double,double (maximum within this bounding box)
 *  - crs : URI (Reference to definition of the CRS)
 *  - dimensions : int 
 * 
 * Note : support only 2D bounding box.
 *
 * @param value the char* containing the KVP bouding box
 * @return a map containing all the bounding box keys
 */
map* parseBoundingBox(const char* value){
  map *res=NULL;
  if(value!=NULL){
    char *cv,*cvp;
    cv=strtok_r((char*) value,",",&cvp);
    int cnt=0;
    int icnt=0;
    char *currentValue=NULL;
    while(cv){
      if(cnt<2)
        if(currentValue!=NULL){
          char *finalValue=(char*)malloc((strlen(currentValue)+strlen(cv)+1)*sizeof(char));
          sprintf(finalValue,"%s%s",currentValue,cv);
          switch(cnt){
          case 0:
            res=createMap("lowerCorner",finalValue);
            break;
          case 1:
            addToMap(res,"upperCorner",finalValue);
            icnt=-1;
            break;
          }
          cnt++;
          free(currentValue);
          currentValue=NULL;
          free(finalValue);
        }
        else{
          currentValue=(char*)malloc((strlen(cv)+2)*sizeof(char));
          sprintf(currentValue,"%s ",cv);
        }
      else
        if(cnt==2){
          addToMap(res,"crs",cv);
          cnt++;
        }
        else
          addToMap(res,"dimensions",cv);
            icnt++;
            cv=strtok_r(NULL,",",&cvp);
    }
  }
  return res;
}

/**
 * Print an ows:BoundingBox XML document
 *
 * @param m the maps containing the settings of the main.cfg file
 * @param boundingbox the maps containing the boundingbox definition
 * @param file the file to print the BoundingBox (if NULL then print on stdout)
 * @see parseBoundingBox, printBoundingBox
 */
void printBoundingBoxDocument(maps* pmsConf,maps* boundingbox,FILE* file){
  if(file==NULL)
    rewind(stdout);
  xmlNodePtr n;
  xmlDocPtr doc;
  xmlNsPtr ns_ows,ns_xsi;
  xmlChar *xmlbuff;
  int buffersize;
  char *encoding=getEncoding(pmsConf);
  map *tmp;
  if(file==NULL){
    int pid=0;
    tmp=getMapFromMaps(pmsConf,"lenv","sid");
    if(tmp!=NULL)
      pid=atoi(tmp->value);
    if(pid==getpid()){
      printf("Content-Type: text/xml; charset=%s\r\nStatus: 200 OK\r\n\r\n",encoding);
    }
    fflush(stdout);
  }

  doc = xmlNewDoc(BAD_CAST "1.0");
  int owsId=zooXmlAddNs(NULL,"http://www.opengis.net/ows/1.1","ows");
  ns_ows=usedNs[owsId];
  n = xmlNewNode(ns_ows, BAD_CAST "BoundingBox");
  xmlNewNs(n,BAD_CAST "http://www.opengis.net/ows/1.1",BAD_CAST "ows");
  int xsiId=zooXmlAddNs(n,"http://www.w3.org/2001/XMLSchema-instance","xsi");
  ns_xsi=usedNs[xsiId];
  xmlNewNsProp(n,ns_xsi,BAD_CAST "schemaLocation",BAD_CAST "http://www.opengis.net/ows/1.1 http://schemas.opengis.net/ows/1.1.0/owsCommon.xsd");
  map *tmp1=getMap(boundingbox->content,"value");
  tmp=parseBoundingBox(tmp1->value);
  printBoundingBox(ns_ows,n,tmp);
  xmlDocSetRootElement(doc, n);

  xmlDocDumpFormatMemoryEnc(doc, &xmlbuff, &buffersize, encoding, 1);
  if(file==NULL)
    printf("%s",xmlbuff);
  else{
    fprintf(file,"%s",xmlbuff);
  }

  if(tmp!=NULL){
    freeMap(&tmp);
    free(tmp);
  }
  xmlFree(xmlbuff);
  xmlFreeDoc(doc);
  xmlCleanupParser();
  zooXmlCleanupNs();

}

/**
 * Print a StatusInfo XML document.
 * a statusInfo map should contain the following keys:
 *  * JobID corresponding to usid key from the lenv section
 *  * Status the current state (Succeeded,Failed,Accepted,Running)
 *  * PercentCompleted (optional) the percent completed
 *  * Message (optional) any messages the service may wish to share
 *
 * @param conf the maps containing the settings of the main.cfg file
 * @param statusInfo the map containing the statusInfo definition
 * @param req the WPS requests (GetResult, GetStatus or Dismiss)
 */
void printStatusInfo(maps* conf,map* statusInfo,char* req){
  rewind(stdout);
  xmlNodePtr n,n1;
  xmlDocPtr doc;
  xmlNsPtr ns;
  xmlChar *xmlbuff;
  int buffersize;
  char *encoding=getEncoding(conf);
  map *tmp;
  int pid=0;
  printf("Content-Type: text/xml; charset=%s\r\nStatus: 200 OK\r\n\r\n",encoding);

  map* version=getMapFromMaps(conf,"main","rversion");
  int vid=getVersionId(version->value);

  doc = xmlNewDoc(BAD_CAST "1.0");
  n1=printWPSHeader(doc,conf,req,"StatusInfo",version->value,1);

  map* val=getMap(statusInfo,"JobID");
  int wpsId=zooXmlAddNs(NULL,schemas[vid][2],"wps");
  ns=usedNs[wpsId];
  n = xmlNewNode(ns, BAD_CAST "JobID");
  xmlAddChild(n,xmlNewText(BAD_CAST val->value));

  xmlAddChild(n1,n);

  val=getMap(statusInfo,"Status");
  n = xmlNewNode(ns, BAD_CAST "Status");
  xmlAddChild(n,xmlNewText(BAD_CAST val->value));

  xmlAddChild(n1,n);

  if(strncasecmp(val->value,"Failed",6)!=0 &&
     strncasecmp(val->value,"Succeeded",9)!=0){
    val=getMap(statusInfo,"PercentCompleted");
    if(val!=NULL){
      n = xmlNewNode(ns, BAD_CAST "PercentCompleted");
      xmlAddChild(n,xmlNewText(BAD_CAST val->value));
      xmlAddChild(n1,n);
    }

    val=getMap(statusInfo,"Message");
    if(val!=NULL){    
      xmlAddChild(n1,xmlNewComment(BAD_CAST val->value));
    }
  }
  xmlDocSetRootElement(doc, n1);

  xmlDocDumpFormatMemoryEnc(doc, &xmlbuff, &buffersize, encoding, 1);
  printf("%s",xmlbuff);

  xmlFree(xmlbuff);
  xmlFreeDoc(doc);
  xmlCleanupParser();
  zooXmlCleanupNs();

}

