    tmpMap=getMapFromMaps(conf,"identification","title");
    if(tmpMap!=NULL){
      json_object_object_add(res1,"title",json_object_new_string(_(tmpMap->value)));
      json_object_object_add(res5,"description",json_object_new_string(_(tmpMap->value)));
