}

void QueryCallback(void *data, ares_status_t status, size_t timeouts,
                   const ares_dns_record_t *dnsrec) {
  EXPECT_NE(nullptr, data);
  if (data == nullptr)
    return;

  QueryResult* result = reinterpret_cast<QueryResult*>(data);
  result->done_ = true;
