    dtype: DT_DOUBLE
    tensor_shape {
      dim { size: 2 }
    }
    double_val: 8.0
    double_val: 9.0
    )",
                                          &tensormap["double_scalar_tensor"]));

  ASSERT_TRUE(TextFormat::ParseFromString(R"(
    dtype: DT_STRING
    tensor_shape {
      dim { size: 2 }
      dim { size: 2 }
    }
    string_val: "hello"
    string_val: "world"
    string_val: "tf"
    string_val: "serving"
    )",
                                          &tensormap["str_tensor_bytes"]));

  string json;
  TF_EXPECT_OK(
      MakeJsonFromTensors(tensormap, JsonPredictRequestFormat::kRow, &json));
  TF_EXPECT_OK(CompareJson(json, R"({
    "predictions": [
      {
        "double_scalar_tensor": 8.0,
        "float_tensor": [1.0],
        "int_tensor": [[1, 2], [3, 4], [5, 6]],
        "str_tensor": ["foo", "bar"],
