 *
 *  @{
 */

/**
 * \file
 *
 * \author Eric Leblond <eric@regit.org>
 *
 * AF_PACKET socket acquisition support
 *
 */

#define SC_PCAP_DONT_INCLUDE_PCAP_H 1
#include "suricata-common.h"
